  "ui.wpAdminAgentFrameApp.feedback103": "هدف خواندن انتخاب‌شدهٔ {value1} در زمینهٔ فعلی مدیریت WordPress مجاز نیست. تغییری ندادم.",
  "ui.wpAdminAgentFrameApp.feedback104": "تأیید مجدد مجوز نوشتهٔ WordPress صریحاً انتخاب‌شدهٔ {value1} ممکن نشد. تغییری ندادم.",
  "ui.wpAdminAgentFrameApp.feedback105": "بارگذاری کامل سند فعلی Gutenberg ممکن نشد ({value1}). تغییری ندادم.",
  "ui.wpAdminAgentFrameApp.feedback106": "سند فعلی Gutenberg فقط به‌صورت تصویر وضعیت قطعه‌بندی‌شده و مقید موجود است. تا خواندن همهٔ قطعات لازم، ویرایش کل سند آماده نمی‌شود. تغییری ندادم.",
  "ui.wpAdminAgentFrameApp.feedback107": "نوشتهٔ فعلی Gutenberg تغییرات ذخیره‌نشده در ویرایشگر دارد. پیش از خواندن یا آماده‌سازی ویرایش آگاه از محتوا توسط Pixflow، آن را ذخیره یا به‌روزرسانی کنید. تغییری ندادم.",
  "ui.wpAdminAgentFrameApp.feedback108": "پاک‌کردن همهٔ بلوک‌های Gutenberg فعلاً پشتیبانی نمی‌شود. Pixflow درخواست را به جایگزینی خالی تعبیر نکرد و چیزی تغییر نکرد.",
  "ui.wpAdminAgentFrameApp.feedback109": "Pixflow نتوانست تشخیص دهد این پیام پاسخ پرسش در انتظار است یا درخواست تازه‌ای آغاز می‌کند. بازبینی آماده نشد و چیزی تغییر نکرد.",
  "ui.wpAdminAgentFrameApp.feedback110": "سند فعلی Gutenberg قطعه‌بندی شده و کامل خوانده نشده است؛ بنابراین Pixflow نمی‌تواند بازبینی کل سند را آماده کند. تغییری ندادم.",
  "ui.wpAdminAgentFrameApp.feedback111": "جایگزینی کامل Gutenberg صریحاً درخواست نشده بود، بنابراین Pixflow از جایگزینی سند فعلی خودداری کرد. چیزی تغییر نکرد.",
  "ui.wpAdminAgentFrameApp.feedback112": "Pixflow نتوانست پس از اقدام قبلی مجوز شیء WordPress را تازه کند. اقدامات قبلی بازگردانده می‌شوند.",
  "ui.wpAdminAgentFrameApp.feedback113": "نوشتهٔ پیش‌نیاز با شناسهٔ معتبر WordPress ساخته نشد. اقدامات قبلی بازگردانده می‌شوند.",
