  "ui.bricksExtensions.modules.8": "رفع نوارشدگی گرادیان",
  "ui.bricksExtensions.modules.9": "کلید اختیاری هموارسازی را به کنترل‌های بومی گرادیان عناصر Bricks اضافه می‌کند.",
  "ui.bricksExtensions.modules.10": "GSAP و افزوده‌های پویانمایی انتخابی را سراسری یا فقط در صفحات Bricks فعال‌شده بارگذاری می‌کند.",
  "ui.bricksExtensions.modules.11": "پیکان‌های اسلایدر و نوارهای پیشرفت کتابخانهٔ Pixflow را سراسری یا برای هر صفحه فعال می‌کند.",
  "ui.bricksExtensions.cookie_platforms.12": "پیش‌فرض‌ها و به‌روزرسانی‌های رضایت Microsoft را در صف قرار می‌دهد.",
  "ui.bricksExtensions.cookie_platforms.13": "فرمان‌های اعطا و لغو مجوز Meta را می‌فرستد.",
  "ui.bricksExtensions.cookie_platforms.14": "فرمان‌های رضایت Pinterest را می‌فرستد.",
  "ui.bricksExtensions.cookie_platforms.15": "ردیابی تنظیم‌شدهٔ TikTok را مشروط به رضایت می‌کند.",
  "ui.bricksExtensions.cookie_platforms.16": "ردیابی تنظیم‌شدهٔ Snapchat را مشروط به رضایت می‌کند.",
  "ui.bricksExtensions.cookie_platforms.17": "ردیابی تنظیم‌شدهٔ LinkedIn را مشروط به رضایت می‌کند.",
  "ui.bricksExtensions.cookie_services.18": "محتوای جاسازی‌شدهٔ YouTube",
  "ui.bricksExtensions.cookie_services.19": "محتوای جاسازی‌شدهٔ Vimeo",
  "ui.bricksExtensions.two_factor_methods.20": "راه‌اندازی با هر اپ احراز هویت سازگار شش‌رقمی را مجاز می‌کند.",
  "ui.bricksExtensions.two_factor_methods.21": "کدهای کوتاه‌مدت ارسال‌شده به ایمیل حساب WordPress کاربر را مجاز می‌کند.",
  "ui.bricksExtensions.two_factor_methods.22": "Windows Hello، Touch ID، Face ID، زیست‌سنجی و کلیدهای FIDO2 را مجاز می‌کند.",
