  "ui.finalOnboarding.44e30ed15f": "BYOK به کلید API نیاز دارد. ارائه‌دهندهٔ هوش مصنوعی هزینهٔ مصرف API را جدا از اشتراک CLI محاسبه می‌کند؛ بنابراین ممکن است به‌جای مصرف سهمیهٔ شامل‌شده یا هفتگی حساب CLI، هزینهٔ اضافی داشته باشد.",
