  "ui.mediaStarter.image1.title": "پرترهٔ مجله‌ای",
  "ui.mediaStarter.image1.tag": "پرتره",
  "ui.mediaStarter.image1.prompt": "پرترهٔ مجله‌ای نزدیک از یک مدیر خلاق جوان در اواخر دههٔ بیست زندگی، نور طبیعی نرم از پنجره‌های بلند استودیو، پالت خنثی گرم (کرم، خاکستری مایل به قهوه‌ای، مشکی ملایم)، با لنز 85mm و f/1.8 و عمق میدان کم، نگاه واضح مستقیم به دوربین، دانه‌بندی ظریف فیلم و ظاهر بدون آرایش.",
  "ui.mediaStarter.image2.title": "تصویر اصلی محصول",
  "ui.mediaStarter.image2.tag": "تجارت الکترونیک",
  "ui.mediaStarter.image2.prompt": "عکس اصلی لوکس از یک ماگ قهوهٔ سرامیکی مات روی پس‌زمینهٔ کاغذی کرم گرم. نور لبهٔ تند از بالا سمت چپ، سایهٔ ملایم و کشیده به پایین سمت راست و بخار کم از فنجان. برش مربع، ترکیب‌بندی مرکزی، فضای خالی بالا برای تیتر، بدون وسایل اضافی یا دست در کادر.",
  "ui.mediaStarter.image3.title": "تصویرسازی تخت",
  "ui.mediaStarter.image3.tag": "تصویرسازی",
  "ui.mediaStarter.image3.prompt": "تصویرسازی برداری تخت از گوشهٔ دنج مطالعه کنار پنجره‌ای بارانی: شکل‌های هندسی، پالت محدود پنج‌رنگ (کرم، سفالی، سبزآبی تیره، قهوه‌ای سیه‌نای سوخته، مشکی ملایم)، خطوط ظریف 1.5px، بدون گرادیان یا بافت، سایهٔ نرم فقط روی صندلی راحتی پیش‌زمینه.",
  "ui.mediaStarter.video1.title": "رونمایی محصول",
  "ui.mediaStarter.video1.tag": "سینمایی",
  "ui.mediaStarter.video1.prompt": "رونمایی محصول در ۵ ثانیه: بطری مینیمال و لوکس مراقبت از پوست روی سنگ کرم تمیز، نور جانبی نرم از چپ دوربین، حرکت آهستهٔ دوربین به جلو، تغییر ظریف فوکوس از درپوش به برچسب، حرکت محدود، بدون نوشتهٔ روی تصویر یا افراد.",
  "ui.mediaStarter.video2.title": "نمای نزدیک فانوس",
  "ui.mediaStarter.video2.tag": "حال‌وهوا",
  "ui.mediaStarter.video2.prompt": "نمای نزدیک سینمایی ۶ ثانیه‌ای از زن جوانی که فانوس کاغذی درخشانی در جنگل کاج مه‌آلود هنگام ساعت طلایی در دست دارد. عمق میدان کم روی چشم‌ها، حرکت ملایم دوربین به جلو، ذرات شناور در پرتو نور گرم، بدون گفتگو و فقط صدای جنگل.",
  "ui.mediaStarter.video3.title": "دریفت در خیابان نئونی",
  "ui.mediaStarter.video3.tag": "اکشن",
  "ui.mediaStarter.video3.prompt": "نمای تعقیبی ۵ ثانیه‌ای از مسابقهٔ خیابانی شبانه در کوچهٔ سایبرپانکی هنگ‌کنگ با نور نئون. دوربین زاویه‌پایین خودروی اسپرت مشکی مات را هنگام دریفت در پیچ تند دنبال می‌کند، محوشدگی حرکت چرخ‌ها، فلر لنز از تابلوهای نئونی، آسفالت باران‌خورده با بازتاب نورها، بدون نوشته.",
  "ui.mediaStarter.hyperframes1.title": "نمایان‌سازی با ذره‌بین",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "ترکیب‌بندی ۵ ثانیه‌ای با یک خط متن نمایشی ضخیم روی بوم تمیز بساز. ذره‌بین گردی را از چپ به راست روی خط حرکت بده تا شکست ظریف شیشه حروف زیر آن را هنگام عبور تغییر شکل دهد. از HyperFrames html-in-canvas استفاده کن: DOM متن را ثبت و شیدر عدسی را با گذری به سبک vfx-liquid-glass روی آن اجرا کن. متن با CSS خالص و شیشه یک لایهٔ WebGL باشد.",
  "ui.mediaStarter.hyperframes2.title": "صحنهٔ ترمینال CRT",
  "ui.mediaStarter.hyperframes2.tag": "جلوه‌های قدیمی",
  "ui.mediaStarter.hyperframes2.prompt": "ترکیب صفحهٔ CRT بساز: بوم تیره، متن تک‌عرض ترمینال که `npx hyperframes init my-video` را تایپ می‌کند، سپس `claude` را با درخواست «با HTML-in-canvas یک افکت CRT اضافه کن» اجرا می‌کند. شیدر انحنای محدب ظریف، خطوط اسکن، ابیراهی رنگی کم و درخشش فسفری نرم را با html-in-canvas روی DOM زنده اعمال کن. متن ترمینال CSS واقعی بماند تا پیش از گذر شیدر کاملاً واضح باشد.",
  "ui.mediaStarter.hyperframes3.title": "فروپاشی گلیچ",
  "ui.mediaStarter.hyperframes3.tag": "گلیچ",
  "ui.mediaStarter.hyperframes3.prompt": "ترکیب‌بندی ۶ ثانیه‌ای بساز که تیتر اصلی و زیرتیتر یک‌خطی را روی بوم تیره نشان دهد، سپس به گلیچ دیجیتال شدید تبدیل شود: جداسازی کانال‌های RGB، نوارهای جابه‌جایی افقی، پرش کوتاه فریم و بازگشت تمیز نهایی. DOM زنده را با html-in-canvas ثبت و گذر گلیچ را روی آن اجرا کن تا متن زیر شیدر CSS واقعی باشد.",
  "ui.mediaStarter.audio1.title": "گویندگی برند",
  "ui.mediaStarter.audio1.tag": "گفتار",
  "ui.mediaStarter.audio1.prompt": "گویندگی روایی گرم ۳۰ ثانیه‌ای برای ویدیوی معرفی محصول: مطمئن اما محاوره‌ای، سرعت متوسط، با مکثی پس از نام برند. متن: 'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' به انگلیسی با لهجهٔ خنثی آمریکای شمالی.",
  "ui.mediaStarter.audio2.title": "گویندگی آغاز کار",
  "ui.mediaStarter.audio2.tag": "گفتار",
  "ui.mediaStarter.audio2.prompt": "گویندگی دوستانهٔ آغاز کار ۲۰ ثانیه‌ای برای صفحهٔ اولین اجرای برنامهٔ موبایل. لحن آرامش‌بخش و خندان، با سرعتی که توجه را نشان دهد اما روخوانی به نظر نرسد. متن: «به Loop خوش آمدید. بیایید فضای شما را آماده کنیم؛ سه سؤال سریع و آماده‌اید. بعداً می‌توانید همهٔ این‌ها را تغییر دهید.»",
  "ui.mediaStarter.audio3.title": "خواندن بخشی از داستان",
  "ui.mediaStarter.audio3.tag": "گفتار",
  "ui.mediaStarter.audio3.prompt": "خوانش سینمایی ۴۵ ثانیه‌ای از بخش آغازین داستان. بیان بم و سنجیده با نفس میان جمله‌ها و حس صمیمی میکروفون نزدیک. متن: «شهر تکه‌تکه می‌خوابد. تابلوی نئونی بالای پیشخوان رامن سوسو می‌زند. آن سوی خیابان، پنجره‌ای می‌درخشد؛ تنها پنجره‌ای که این سوی نیمه‌شب هنوز روشن است.»",
  "ui.finalWorkspace.72ed7e2a11": "نمونه‌های خانوادهٔ قلم",
