  "ui.seoAudit.aClientReportCanPredateSeveral_d76aee45": "یک گزارش مشتری می‌تواند قبل از انجام چندین بازرسی تهیه شود. تنها بازرسی \"در حال انجام\" مشخص می‌کند که بازرسی قبلی چه زمانی انجام شده است. برای ارائه پیشنهادات، از برنامه کاری فعلی استفاده کنید. گزارش و بازرسی‌ها را جدا نگه دارید. یادداشت‌های قبلی، توصیه‌های قبلی را ثبت می‌کنند و لزوماً اندازه‌گیری‌های دقیق نیستند؛ ممکن است به گزارش‌های قدیمی‌تر نیز اشاره کنند. برای کارهای انجام شده، از اطلاعات تایید شده استفاده کنید. عدم وجود یا عدم تطابق یک بررسی، راه حل نیست.",
  "ui.seoAudit.aCurrentGoogleComparisonWasUnavailable_6c226bcf": "دسترسی به مقایسه فعلی گوگل امکان‌پذیر نبود. در این گزارش، از شواهد بازرسی ذخیره شده استفاده شده است.",
  "ui.seoAudit.aNewRenderedMeasurementConfirmsThe_21bd594c": "یک اندازه‌گیری جدید نشان می‌دهد که متن مورد نظر، حداقل کنتراست مورد نیاز را دارد. پس‌زمینه‌های غیرقابل اندازه‌گیری، همچنان تایید نشده‌اند.",
