  "ui.seoAudit.onlyPreviousreportmeasurementsSuppliesThePriorReport_895e2974": "گزارش‌های قبلی، مجموع‌های عددی و تاریخ‌های اندازه‌گیری را ارائه می‌دهند. در صورت عدم وجود، از توضیحات برای استخراج یا استنباط آنها استفاده نکنید. بازه‌های اندازه‌گیری قبلی و فعلی را از هم جدا نگه دارید. تغییرات را در بازه‌های همپوشان یا نامتقارن، ویژگی‌های مختلف یا فیلترهای تغییر یافته محاسبه نکنید. این موارد را به عنوان غیر قابل مقایسه توصیف کنید. یک تعمیر موفق، لزوماً نشان نمی‌دهد که باعث تغییر در ترافیک شده است.",
