  "ui.seoAudit.theHomepageHoldsItsGoogleAnalytics_c856d366": "صفحه اصلی، تگ Google Analytics را تا زمانی که اجازه استفاده از آن داده شود، حفظ می‌کند. بازدیدهایی که اجازه استفاده را ندهند، ممکن است در GA4 وجود نداشته باشند، بنابراین ترافیک ارگانیک گزارش شده ممکن است تعداد بازدیدهای واقعی را نشان ندهد.",
  "ui.seoAudit.theHomepageSetsAnalyticsStorageTo_36c513cb": "صفحه اصلی به طور پیش‌فرض، ذخیره‌سازی داده‌های تحلیلی را غیرفعال می‌کند. GA4 ممکن است سیگنال‌های محدود بدون کوکی دریافت کند و از مدل‌سازی استفاده کند. آمار ارائه شده نباید به عنوان یک شمارش کامل از بازدیدها در نظر گرفته شود.",
  "ui.seoAudit.theIntendedReferringPageContainsA_53634050": "صفحه مرجع مورد نظر، یک پیوند HTML عمومی به این صفحه قابل دسترس دارد، یا صاحب صفحه، این صفحه بدون پیوند را به عنوان یک صفحه هدف‌دار ثبت می‌کند.",
